script_dir=fileparts(mfilename('fullpath'));root_dir=fileparts(script_dir);w=fullfile(root_dir,'waveforms','12-hall-speed');a=fullfile(root_dir,'assets','12-hall-speed');if ~exist(a,'dir');mkdir(a);end
slow=readtable(fullfile(w,'plecs_slow_25.csv'),'VariableNamingRule','preserve');fast=readtable(fullfile(w,'plecs_fast_400.csv'),'VariableNamingRule','preserve');stop=readtable(fullfile(w,'plecs_stopped_timeout.csv'),'VariableNamingRule','preserve');s=readtable(fullfile(w,'plecs_hall_speed_summary.csv'),'VariableNamingRule','preserve');assert(all(strcmp(s.result,'PASS')));
fig=figure('Color','w','Position',[100 80 1550 1050]);tl=tiledlayout(fig,3,1,'TileSpacing','compact','Padding','compact');title(tl,'Hall edge speed estimation, quantization and timeout');
nexttile;stairs(fast.time_s,fast.hall_code,'LineWidth',1.1);hold on;stairs(slow.time_s,slow.hall_code,'LineWidth',1.1);ylabel('Hall code');grid on;legend('400 rad/s','25 rad/s','Location','eastoutside');
nexttile;plot(fast.time_s,fast.speed_rad_s,'LineWidth',1.3);hold on;stairs(fast.time_s,fast.speed_raw_rad_s,'LineWidth',1.0);plot(fast.time_s,fast.speed_filtered_rad_s,'LineWidth',1.3);ylabel('speed / rad/s');grid on;legend('PLECS actual','edge raw','filtered','Location','eastoutside');
nexttile;stairs(stop.time_s,stop.timeout,'LineWidth',1.3);hold on;plot(stop.time_s,stop.speed_filtered_rad_s,'LineWidth',1.2);xline(0.05,':');ylabel('timeout / speed');xlabel('time / s');grid on;legend('timeout','filtered speed','Location','eastoutside');
exportgraphics(fig,fullfile(a,'hall_speed_quantization_timeout.png'),'Resolution',180);close(fig);fprintf('Generated chapter 12 MATLAB Hall-speed figure. scenarios=%d figures=1\n',height(s));
